142	// In the SQL context, the database provider that we use to expose the
143	// remotesapi interface can choose to either create a newly accessed database
144	// on first access or to return NotFound. Currently we allow creation in the
145	// cluster replication context, where the replicated database should definitely
146	// be made to exist and the accesses are always writes, but we disallow it in
147	// the exposed-as-a-remotesapi-endpoint use case, where the requested database
148	// may just be a typo or a configuration mistake on the part of the user.
149	
150	type CreateUnknownDatabasesSetting bool
151	
152	const CreateUnknownDatabases CreateUnknownDatabasesSetting = true
153	const DoNotCreateUnknownDatabases CreateUnknownDatabasesSetting = false
154	
155	// Returns a remotesrv.DBCache instance which will use the *sql.Context
156	// returned from |ctxFactory| to access a database in the session
157	// DatabaseProvider.
158	func RemoteSrvDBCache(ctxFactory func(context.Context) (*sql.Context, error), createSetting CreateUnknownDatabasesSetting) (remotesrv.DBCache, error) {
159		dbcache := remotesrvStore{ctxFactory, bool(createSetting)}
160		return dbcache, nil
161	}
