26	type hooksDatabase struct {
27		datas.Database
28		db    *DoltDB
29		hooks []CommitHook
30		rsc   *ReplicationStatusController
31	}
32	
33	// CommitHook is an abstraction for executing arbitrary commands after atomic database commits
34	type CommitHook interface {
35		// Execute is arbitrary read-only function whose arguments are new Dataset commit into a specific Database.
36		// The returned values are a callback function and an error. The callback function is
37		// a Wait function which is optional. If returned, it will be registered with the ReplicationStatusController. If the
38		// hook implements NotifyWaitFailedCommitHook, it will be notified if the Wait function returns an error.
39		// The |Error| returned is actually ignored by the caller. It exists primarily for for unit testing. Any error which
40		// happens in a hook should be logged by the hook itself.
41		Execute(ctx context.Context, ds datas.Dataset, db *DoltDB) (func(context.Context) error, error)
42		// ExecuteForWorkingSets returns whether or not the hook should be executed for working set updates
43		ExecuteForWorkingSets() bool
44	}
45	
46	// NotifyWaitFailedCommitHook is an optional interface that can be implemented by CommitHooks.
47	// If a commit hook supports this interface, it can be notified if waiting for
48	// replication in the callback returned by |Execute| failed to complete in time
49	// or returned an error.
50	type NotifyWaitFailedCommitHook interface {
51		NotifyWaitFailed()
52	}
53	
54	func (db hooksDatabase) SetCommitHooks(ctx context.Context, postHooks []CommitHook) hooksDatabase {
55		db.hooks = make([]CommitHook, len(postHooks))
56		copy(db.hooks, postHooks)
57		return db
58	}
59	
60	func (db hooksDatabase) withReplicationStatusController(rsc *ReplicationStatusController) hooksDatabase {
61		db.rsc = rsc
62		return db
63	}
64	
65	func (db hooksDatabase) PostCommitHooks() []CommitHook {
66		toret := make([]CommitHook, len(db.hooks))
67		copy(toret, db.hooks)
68		return toret
69	}
70	
71	func (db hooksDatabase) ExecuteCommitHooks(ctx context.Context, ds datas.Dataset, onlyWS bool) {
72		var wg sync.WaitGroup
73		rsc := db.rsc
74		var ioff int
75		if rsc != nil {
76			ioff = len(rsc.Wait)
77			rsc.Wait = append(rsc.Wait, make([]func(context.Context) error, len(db.hooks))...)
78			rsc.NotifyWaitFailed = append(rsc.NotifyWaitFailed, make([]func(), len(db.hooks))...)
79		}
80		for il, hook := range db.hooks {
81			if !onlyWS || hook.ExecuteForWorkingSets() {
82				i := il
83				hook := hook
84				wg.Add(1)
85				go func() {
86					defer wg.Done()
87					// The error returned is intentionally ignored here. Hooks are expected to log errors themselves. The interface returns
88					// the error primarily for testing purposes.
89					f, _ := hook.Execute(ctx, ds, db.db)
90					if rsc != nil {
91						rsc.Wait[i+ioff] = f
92						if nf, ok := hook.(NotifyWaitFailedCommitHook); ok {
93							rsc.NotifyWaitFailed[i+ioff] = nf.NotifyWaitFailed
94						} else {
95							rsc.NotifyWaitFailed[i+ioff] = func() {}
96						}
97					}
98				}()
99			}
100		}
101		wg.Wait()
102		if rsc != nil {
103			j := ioff
104			for i := ioff; i < len(rsc.Wait); i++ {
105				// compact out any nil entries
106				if rsc.Wait[i] != nil {
107					rsc.Wait[j] = rsc.Wait[i]
108					rsc.NotifyWaitFailed[j] = rsc.NotifyWaitFailed[i]
109					j++
110				}
111			}
112			rsc.Wait = rsc.Wait[:j]
113			rsc.NotifyWaitFailed = rsc.NotifyWaitFailed[:j]
114		}
115	}
116	
117	func (db hooksDatabase) CommitWithWorkingSet(
118		ctx context.Context,
119		commitDS, workingSetDS datas.Dataset,
120		val types.Value, workingSetSpec datas.WorkingSetSpec,
121		prevWsHash hash.Hash, opts datas.CommitOptions,
122	) (datas.Dataset, datas.Dataset, error) {
123		commitDS, workingSetDS, err := db.Database.CommitWithWorkingSet(
124			ctx,
125			commitDS,
126			workingSetDS,
127			val,
128			workingSetSpec,
129			prevWsHash,
130			opts)
131		if err == nil {
132			db.ExecuteCommitHooks(ctx, commitDS, false)
133		}
134		return commitDS, workingSetDS, err
135	}
136	
137	func (db hooksDatabase) Commit(ctx context.Context, ds datas.Dataset, v types.Value, opts datas.CommitOptions) (datas.Dataset, error) {
138		ds, err := db.Database.Commit(ctx, ds, v, opts)
139		if err == nil {
140			db.ExecuteCommitHooks(ctx, ds, false)
141		}
142		return ds, err
143	}
144	
145	func (db hooksDatabase) WriteCommit(ctx context.Context, ds datas.Dataset, commit *datas.Commit) (datas.Dataset, error) {
146		ds, err := db.Database.WriteCommit(ctx, ds, commit)
147		if err == nil {
148			db.ExecuteCommitHooks(ctx, ds, false)
149		}
150		return ds, err
151	}
152	
153	func (db hooksDatabase) SetHead(ctx context.Context, ds datas.Dataset, newHeadAddr hash.Hash, ws string) (datas.Dataset, error) {
154		ds, err := db.Database.SetHead(ctx, ds, newHeadAddr, ws)
155		if err == nil {
156			db.ExecuteCommitHooks(ctx, ds, false)
157		}
158		return ds, err
159	}
160	
161	func (db hooksDatabase) FastForward(ctx context.Context, ds datas.Dataset, newHeadAddr hash.Hash, workingSetPath string) (datas.Dataset, error) {
162		ds, err := db.Database.FastForward(ctx, ds, newHeadAddr, workingSetPath)
163		if err == nil {
164			db.ExecuteCommitHooks(ctx, ds, false)
165		}
166		return ds, err
167	}
168	
169	func (db hooksDatabase) Delete(ctx context.Context, ds datas.Dataset, workingSetPath string) (datas.Dataset, error) {
170		ds, err := db.Database.Delete(ctx, ds, workingSetPath)
171		if err == nil {
172			db.ExecuteCommitHooks(ctx, datas.NewHeadlessDataset(ds.Database(), ds.ID()), false)
173		}
174		return ds, err
175	}
176	
177	func (db hooksDatabase) UpdateWorkingSet(ctx context.Context, ds datas.Dataset, workingSet datas.WorkingSetSpec, prevHash hash.Hash) (datas.Dataset, error) {
178		ds, err := db.Database.UpdateWorkingSet(ctx, ds, workingSet, prevHash)
179		if err == nil {
180			db.ExecuteCommitHooks(ctx, ds, true)
181		}
182		return ds, err
183	}
184	
185	func (db hooksDatabase) Tag(ctx context.Context, ds datas.Dataset, commitAddr hash.Hash, opts datas.TagOptions) (datas.Dataset, error) {
186		ds, err := db.Database.Tag(ctx, ds, commitAddr, opts)
187		if err == nil {
188			db.ExecuteCommitHooks(ctx, ds, false)
189		}
190		return ds, err
191	}
192	
193	func (db hooksDatabase) SetTuple(ctx context.Context, ds datas.Dataset, val []byte) (datas.Dataset, error) {
194		ds, err := db.Database.SetTuple(ctx, ds, val)
195		if err == nil {
196			db.ExecuteCommitHooks(ctx, ds, false)
197		}
198		return ds, err
199	}
